        requireCapability(!findTool(), 'Công cụ tư liệu trùng tên đang chạy, vui lòng tắt tiện ích mở rộng cũ hoặc script bị lặp.');
        context.registerFunctionTool({ ...compatibleTool(makeTool()).function, displayName:'Tài liệu ngọn sóng (Không cần gọi)',
            shouldRegister:() => false, action:async () => 'Dữ liệu đã được đặt đầy đủ tại wave_context_reference trong phần giải thích của, không cần gọi lại nữa. Vui lòng nhấn messages Phản hồi giao hẹn bàn giao trong lượt.',
            formatMessage:() => 'Tài liệu đã được cung cấp, đang tiếp tục sáng tác.', stealth:false });
        ownedTool = findTool();
        requireCapability(ownedTool, 'Công cụ tư liệu sau khi đăng ký không được SillyTavern nhận diện, chưa khởi động việc sắp xếp.');
        const handler = data => {
            if (disposed) return;
            const type = data?.type ?? legacyType;
            legacyType = undefined;
            if (!hasContextMarkers(data?.messages)) { setState('unrelated'); return; }
            if (!waveRegisterRequest(data, type)) { setState('unrelated'); return; }
            try {
                const current = getContext();
                const input = { ...data, type, custom_prompt_post_processing:data.custom_prompt_post_processing
                    ?? current.chatCompletionSettings?.custom_prompt_post_processing ?? '' };
                const result = transformRequest(input, {
                    canUseTools:typeof type === 'string' && current.canPerformToolCalls(type),
                    toolUnavailableReason:waveToolUnavailableReason(current, input),
                    squashSystemMessages:current.chatCompletionSettings?.squash_system_messages === true });
                if (result.status === 'unrelated') { WAVE_PENDING_REQUESTS.delete(data); setState('unrelated'); return; }
                // Prepare all transformed fields before mutating the outgoing request.
                const nextTools = result.status === 'moved'
                    ? result.request.tools.map(tool => tool.function?.name === TOOL_NAME ? compatibleTool(tool) : tool) : undefined;
                data.messages = result.request.messages;
                if (result.status === 'moved') {
                    data.tools = nextTools;
                    data.tool_choice = result.request.tool_choice;
                    setState('moved', '', result.stats);
                    if (typeof runtime.getButtonEvent !== 'function') notify('info', `Lượt này đã sắp xếp ${result.stats.movedMessages} mục tư liệu. Nhấp vào thông báo này để mở trạng thái gửi tư liệu。`);
                } else {
                    const reason = typeof type !== 'string' ? 'Yêu cầu cũ không cung cấp loại tạo, cũng không có sự kiện tạo tương ứng.' : result.reason;
                    setState('fallback', reason);
                    const r = waveRecovery(reason);
                    notify('warning', `Đã chuyển sang gửi bình thường, tư liệu vẫn nằm trong tin nhắn thường. Lý do：${r.cause} Phải làm sao：${r.remedy}`);
