                    WAVE_PLAN_ERRORS.set(data, error);
                    setState('error', error.message);
                    notify('error', error.message);
                    return;
                }
                WAVE_PENDING_REQUESTS.delete(data);
                setState('error', 'Lượt này xử lý bất thường (' + (error?.name || 'Error') + '); chưa gửi các trường đã sắp xếp. Hãy xem lỗi Lãng Triều trong console.');
                console.error('[Ta chính là Lãng Triều] Sắp xếp yêu cầu thất bại', error);
                const r = waveRecovery(state.reason);
                notify('error', `Lý do：${r.cause} Phải làm sao：${r.remedy}`);
            }
        };
        listen(runtime.tavern_events.CHAT_COMPLETION_SETTINGS_READY, handler, true);
        const clearType = () => { legacyType = undefined; };
        for (const name of ['GENERATION_STARTED','GENERATION_ENDED','GENERATION_STOPPED']) {
            if (runtime.tavern_events[name]) listen(runtime.tavern_events[name], clearType);
        }
        if (runtime.tavern_events.GENERATION_AFTER_COMMANDS) listen(runtime.tavern_events.GENERATION_AFTER_COMMANDS, (type, _options, dryRun) => {
            legacyType = dryRun !== true && typeof type === 'string' ? type : undefined;
        });
        for (const name of ['CHAT_CHANGED','OAI_PRESET_CHANGED_AFTER']) {
            if (runtime.tavern_events[name]) listen(runtime.tavern_events[name], () => { clearType(); WAVE_PENDING_REQUESTS.clear(); setState('waiting'); });
        }
        notify('success', 'Đã bật. Nhấn "Lãng Triều·Trạng thái" để xem kết quả xử lý tư liệu, thống kê khiên và chuyển cấp khiên.');
        return { dispose:cleanup, getStatus:() => structuredClone(state), openStatus:ui.open };
    } catch (error) {
        // Remove only our tool and request hooks. Keep the diagnostic button until unload.
        try { if (ownedTool && findTool() === ownedTool) context.unregisterFunctionTool(TOOL_NAME); } catch {}
        ownedTool = undefined;
        setState('setup', error instanceof Error ? error.message : 'Khởi động script thất bại.');
        const r = waveRecovery(state.reason);
        notify('error', `Chưa khởi động sắp xếp tài liệu. Nguyên nhân：${r.cause} Phải làm sao：${r.remedy} Gợi ý cụ thể：${state.reason}`);
        void ui.open();
        return { dispose:cleanup, getStatus:() => structuredClone(state), openStatus:ui.open };
    }
}

