    for (const [needle, choices] of WAVE_SHIELD_VARIANTS) {
        if (!out.includes(needle)) continue;
        const parts = out.split(needle);
        let rebuilt = parts[0];
        for (let i = 1; i < parts.length; i++) rebuilt += waveShieldPick(choices) + parts[i];
        out = rebuilt;
    }
    const lines = out.split(WAVE_SHIELD_NL);
    if (lines.length > 1) {
        let sinceAnchor = 0;
        const longBlock = out.length >= 240;
        for (let i = 0; i < lines.length - 1; i++) {
            let line = lines[i].trimEnd();
            const prefix = waveShieldListPrefix(line);
            if (prefix && waveShieldRandom() < 0.55) {
                line = prefix.head + ' '.repeat(waveShieldRandInt(1, 3)) + line.slice(prefix.head.length + prefix.gap);
            }
            const tail = line.slice(-1);
            if (line.length > 6 && !'>}%`~]'.includes(tail) && !waveShieldLineBlocked(line) && waveShieldRandom() < 0.65) {
                line += ' '.repeat(waveShieldRandInt(1, 4));
