    for(const [index,item] of optionItems.entries()){
      const li=document.createElement('li'),button=document.createElement('button');
      button.type='button';button.setAttribute('data-wave-choice',String(index));
      if(item.unavailable)button.setAttribute('data-wave-unavailable','');
      const number=document.createElement('span');number.setAttribute('data-wave-choice-number','');number.textContent=String(item.number);
      const copy=document.createElement('span'),category=document.createElement('span');category.setAttribute('data-wave-choice-category','');category.textContent=item.category;
      copy.append(category,document.createTextNode(item.action));button.append(number,copy);li.append(button);list.append(li);
