      copy.append(category,document.createTextNode(item.action));button.append(number,copy);li.append(button);list.append(li);
    }
    target.append(list);updateActions(actions.getState());
  }
  function dispose() {disposed=true;if(timer!==null)clearTimeout(timer);timer=null;actions?.dispose();}
  async function refresh() {
    if (disposed) return;
    const panel=document.querySelector('[data-wave-ui]'), copy=document.querySelector('[data-wave-copy]'), phase=document.querySelector('[data-wave-phase]');
    let busy=false;
    try {
      if (typeof getCurrentMessageId!=='function' || typeof getChatMessages!=='function') throw new Error('Không thể đọc tin nhắn này: Vui lòng đảm bảo bạn đang dùng giao diện tầng của TavernHelper và đã bật bộ render. Ứng dụng tương thích cũng cần cung cấp giao diện đọc tin nhắn.。');
      const id=getCurrentMessageId();
      const rows=await getChatMessages(id);
      const row=rows.find(item=>item.message_id===id);
      if (!row || typeof row.message!=='string') throw new Error('Nội dung tin nhắn này chưa được lưu hoặc chưa sẵn sàng; vui lòng đợi phản hồi hoàn tất rồi tải lại tin nhắn.。');
      const blocks=extract(row.message,config.kind);
      if (!blocks.length) throw new Error('Tin nhắn này thiếu mục tương ứng hoàn chỉnh, hoặc có regex khác đã thay đổi thẻ nguồn; vui lòng kiểm tra nội dung gốc.。');
      const block=blocks[occurrence(blocks.length)];
      if (!block) throw new Error('Không tìm thấy nội dung tương ứng với bảng này; vui lòng tải lại tin nhắn.。');
      busy=config.kind==='plan' && block.state==='';
      panel.setAttribute('data-wave-state',block.state);
      if (phase) {phase.textContent=busy?'Đang lên ý tưởng':'Đã lập kế hoạch xong';phase.toggleAttribute('data-wave-busy',busy);phase.toggleAttribute('data-wave-done',!busy);}
      const key=block.text+'\u0000'+block.state;
      if (last!==key) {
        if(config.kind==='options'&&actions)renderOptions(copy,block.text);
        else if(config.kind==='mind'){
          const name=/^\s*\*\*([^*\n]{1,24})\*\*\s*(?:\r?\n|$)/.exec(block.text);
          document.querySelector('[data-wave-title]').textContent=name?name[1]+' · Tiếng lòng':'Tiếng lòng nhân vật';
          renderText(copy,name?block.text.slice(name[0].length):block.text);
        }else renderText(copy,block.text);
        last=key;
      }
      panel.removeAttribute('data-wave-error');failures=0;
    } catch (error) {
      panel.setAttribute('data-wave-error','');
