      document.querySelector('[data-wave-copy]').addEventListener('click',event=>{
        const button=event.target.closest('[data-wave-choice]');
        if(!button||button.disabled)return;
        const item=optionItems[Number(button.getAttribute('data-wave-choice'))];
        if(item&&!item.unavailable)void actions.pick(item.action);
      });
    }
    refresh();
  }
  return {extract,renderText,markerKind,getFrameKind,start,dispose};
}

createWavePanelRuntime({"kind":"mind"}).start();
