// View preference only; the control lives in the existing panel heading.
function createWaveTheme(view = window, root = document.documentElement) {
  const key = 'wave-ui-theme-v1', eventName = 'wave-ui-theme-change-v1';
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const media = view.matchMedia?.('(prefers-color-scheme: dark)');
  const valid = value => ['auto', 'day', 'night'].includes(value);
  let mode = 'auto';
  try { mode = hub.localStorage.getItem(key) || 'auto'; } catch {}
  if (valid(hub.__waveUiThemeV1)) mode = hub.__waveUiThemeV1;
  if (!valid(mode)) mode = 'auto';
  const isNight = () => mode === 'night' || mode === 'auto' && !!media?.matches;
  const paint = () => {
    const night = isNight();
    root.setAttribute('data-wave-theme', night ? 'night' : 'day');
    root.querySelectorAll('[data-wave-theme-toggle]').forEach(button => {
      button.textContent = night ? '☾' : '☀';
      button.setAttribute('aria-pressed', String(night));
      button.title = night ? 'Hiện tại là chế độ tối, nhấn để chuyển sang chế độ sáng' : 'Hiện tại là chế độ sáng, nhấn để chuyển sang chế độ tối';
    });
  };
  const receive = event => { if (valid(event.detail)) { mode = event.detail; paint(); } };
  const toggle = event => {
    const button = event.target.closest?.('[data-wave-theme-toggle]');
    if (!button || !root.contains(button)) return;
    // Cancels the summary's default toggle as well as its click propagation.
    event.preventDefault(); event.stopPropagation();
    mode = isNight() ? 'day' : 'night';
    hub.__waveUiThemeV1 = mode;
    try { hub.localStorage.setItem(key, mode); } catch {}
    hub.dispatchEvent(new hub.CustomEvent(eventName, { detail: mode }));
    paint();
  };
  const storage = event => { if (event.key === key) receive({detail: event.newValue || 'auto'}); };
  root.addEventListener('click', toggle);
  hub.addEventListener(eventName, receive);
  hub.addEventListener('storage', storage);
  media?.addEventListener?.('change', paint);
  paint();
  const dispose = () => {
    root.removeEventListener('click', toggle);
    hub.removeEventListener(eventName, receive);
    hub.removeEventListener('storage', storage);
    media?.removeEventListener?.('change', paint);
    view.removeEventListener('pagehide', dispose);
  };
  view.addEventListener('pagehide', dispose, {once:true});
  return { paint, dispose };
}

createWaveTheme();

// Apply the console preference to this independently rendered message frame.
function watchWaveRegexFont(view = window) {
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const paint = () => {
    const scale = hub.document.documentElement.style.getPropertyValue('--wave-regex-scale');
    view.document.documentElement.style.setProperty('--wave-regex-scale', scale || '1');
  };
  hub.addEventListener('wave-regex-font-change', paint);
  view.addEventListener('pagehide', () => hub.removeEventListener('wave-regex-font-change', paint), { once: true });
  paint();
}
watchWaveRegexFont();

// Stock SillyTavern send UI source: 8172dcd0ee672d3cd9a5e5f7af134f91a45cd2b8.
// No generated text is ever executed as a command or HTML.
function createWaveActionController(runtime) {
  const storageKey='wave.ui.actionMode.v1', lockKey='__waveActionPending030';
  let mode='draft',pending=false,submitted=false,feedback='',error=false,disposed=false;
  let listener=()=>{},timer=null,wake=null,ownedLock=null,hostWindow;
  const plain=value=>String(value).replace(/\*\*([^*\n]+)\*\*/g,(_all,part)=>part).replace(/`([^`\n]+)`/g,(_all,part)=>part).trim();
  function parse(text) {
    const items=[];
    // Recover a glued heading only when the explicit numbered, bold category follows.
    const separate = String(text).replace(/([^\d\r\n])(?=\d+[.、)）]\s*\*\*[^*\n]+\*\*\s*[:：])/gu, prev => prev + '\n');
    for(const line of separate.trim().split(/\r?\n/)){
      const match=/^\s*(\d+)\s*[.、)）:：]\s*(.*)$/.exec(line)
        || /^\s*(\d+)\s*$/.exec(line)
        || /^\s*(\d+)\s+(\*\*[^*\n]+\*\*\s*[:：].*)$/.exec(line);
      if(match)items.push({number:Number(match[1]),raw:match[2]||''});
      else if(items.length)items[items.length-1].raw+='\n'+line;
      else if(line.trim())return [];
    }
    if(!items.length||items.some((item,i)=>!Number.isSafeInteger(item.number)||item.number!==i+1))return [];
    const parsed=items.map(item=>{
      // Explicit bold category first. Plain labels remain compatible with old replies.
      const raw=item.raw.trim();
      const match=/^\*\*([^*\n]+)\*\*\s*(?:[:：]|[—-]{1,2})\s*([\s\S]*)$/.exec(raw)
        || /^([^:：\n]{1,40})\s*[:：]\s*([\s\S]*)$/.exec(raw)
        || /^(稳步推进|积极行动|出奇制胜|暧昧挑逗|彻底发癫|Tiến bước vững chắc|Hành động tích cực|Bất ngờ xuất chiêu|Mập mờ khiêu khích|Hoàn toàn phát điên)\s*[—-]{1,2}\s*([\s\S]*)$/.exec(raw);
      const action=plain(match?match[2]:raw);
      return {number:item.number,category:match?plain(match[1]):'Hành động '+item.number,action,
        unavailable:/^(?:本场景)?不适用[。.!！]?$|^(?:Không áp dụng(?: cho cảnh này)?)[。.!！]?$/i.test(action)};
    });
    // An empty last item is still streaming/malformed; keep all original text visible.
    return parsed.some(item=>!item.action)?[]:parsed;
  }
  function getHost(){
    try{
      const doc=runtime.parent?.document ?? runtime.document;
      if(!doc?.body)throw new Error();
      const input=doc.querySelector('#send_textarea');
      if(!input||typeof input.value!=='string')throw new Error();
      hostWindow=doc.defaultView;
      return {doc,input,win:doc.defaultView};
    }catch{throw new Error('Không tìm thấy ô nhập liệu của SillyTavern; vui lòng xác nhận hiện tại là bản gốc SillyTavern，và làm mới trang rồi thử lại。');}
  }
  function getState(){return {mode,pending,submitted,feedback,error};}
  function announce(text,isError=false){feedback=text;error=isError;if(!disposed)listener(getState());}
  function loadMode(){try{mode=runtime.localStorage?.getItem(storageKey)==='send'?'send':'draft';}catch{mode='draft';}}
  function setMode(value){mode=value==='send'?'send':'draft';try{runtime.localStorage?.setItem(storageKey,mode);}catch{}if(!disposed)listener(getState());}
  function storageChanged(event){if(event.key===storageKey){loadMode();if(!disposed)listener(getState());}}
  function writeInput(host,value){host.input.value=value;host.input.dispatchEvent(new host.win.Event('input',{bubbles:true}));}
  function payload(action){
    // Do not add a sentence prefix. Fullwidth braces keep a model-supplied
    // macro from being interpreted by substituteParams.
