      try{const st=getWindow()?.SillyTavern;context=st?.getContext?.();if(context)break;}catch{}
    }
    const id=context?.getCurrentChatId?.() ?? context?.chatId;
    if(id===undefined||id===null||id==='')throw new Error('Vui lòng mở một đoạn chat nhân vật trước khi chọn hành động。');
    return {key:String(context.characterId??'')+'|'+String(context.groupId??'')+'|'+String(id),context};
  }
  function releaseLock(){if(hostWindow&&hostWindow[lockKey]===ownedLock)delete hostWindow[lockKey];ownedLock=null;}
  function pause(){return new Promise(resolve=>{wake=resolve;timer=runtime.setTimeout(()=>{timer=null;wake=null;resolve();},200);});}
  async function pick(action){
    if(disposed||pending||submitted)return;
    const text=payload(action);
    if(!plain(action))return;
    try{
      const host=getHost();
      if(mode==='draft'){
        const current=host.input.value;
        if(current===text||current.endsWith('\n'+text)){announce('Hành động này đã có trong ô nhập liệu。');return;}
        writeInput(host,current?current+(current.endsWith('\n')?'':'\n')+text:text);
        host.input.focus();host.input.setSelectionRange?.(host.input.value.length,host.input.value.length);
        announce(current?'Đã thêm vào ô nhập liệu。':'Đã điền vào ô nhập liệu。');return;
      }
      if(host.input.value.trim())throw new Error('Ô nhập liệu đang có nội dung chưa gửi. Vui lòng xử lý bản nháp trước, hoặc chuyển sang "Điền vào ô nhập liệu" để thêm hành động。');
      if(/^\s*\//.test(text))throw new Error('Tùy chọn này bắt đầu bằng / ở đầu, có thể bị SillyTavern nhận diện là lệnh. Vui lòng chuyển sang "Điền vào ô nhập liệu", kiểm tra lại rồi gửi thủ công。');
      if(host.doc.body.dataset.generating==='true'||host.win[lockKey])throw new Error('SillyTavern đang xử lý yêu cầu trước, vui lòng đợi hoàn tất rồi chọn tiếp。');
