      const before=chatKey();
      if(before.context.onlineStatus==='no_connection')throw new Error('API hiện tại chưa kết nối. Vui lòng kết nối mô hình trước, hoặc chuyển sang“Điền vào ô nhập liệu”。');
      if(typeof runtime.getChatMessages!=='function')throw new Error('Thiếu API đọc tin nhắn, không thể đối chiếu xem đã gửi hay chưa. Vui lòng chuyển sang“Điền vào ô nhập”。');
