      const id=getCurrentMessageId();
      const rows=await getChatMessages(id);
      const row=rows.find(item=>item.message_id===id);
      if (!row || typeof row.message!=='string') throw new Error('Nội dung tin nhắn này chưa được lưu hoặc chưa sẵn sàng; vui lòng đợi phản hồi hoàn tất rồi tải lại tin nhắn.。');
