    const frames=Array.from(floor.querySelectorAll('iframe[id^="TH-message--"]')).filter(el=>getFrameKind(el)===config.kind);
    const index=frames.indexOf(frame);
    if (index<0 || frames.length!==blockCount) throw new Error('Số lượng bảng cùng loại chưa khớp với tin nhắn gốc. Nếu tải lại vẫn bị, hãy kiểm tra xem có biểu thức chính quy (regex) nào ẩn bớt tiếng lòng không, cũng như khả năng tương thích giao diện của ứng dụng.。');
    return index;
  }
  let timer=null,disposed=false,last='',failures=0,actions=null,optionItems=[];
