    if (!frame || !floor) throw new Error('Tin nhắn này có nhiều mục cùng loại nhưng ứng dụng không cung cấp khung chứa nhận diện được; vui lòng cập nhật TavernHelper rồi tải lại tin nhắn này.。');
    const frames=Array.from(floor.querySelectorAll('iframe[id^="TH-message--"]')).filter(el=>getFrameKind(el)===config.kind);
