// View preference only; the control lives in the existing panel heading.
function createWaveTheme(view = window, root = document.documentElement) {
  const key = 'wave-ui-theme-v1', eventName = 'wave-ui-theme-change-v1';
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const media = view.matchMedia?.('(prefers-color-scheme: dark)');
  const valid = value => ['auto', 'day', 'night'].includes(value);
  let mode = 'auto';
  try { mode = hub.localStorage.getItem(key) || 'auto'; } catch {}
  if (valid(hub.__waveUiThemeV1)) mode = hub.__waveUiThemeV1;
  if (!valid(mode)) mode = 'auto';
  const isNight = () => mode === 'night' || mode === 'auto' && !!media?.matches;
  const paint = () => {
    const night = isNight();
    root.setAttribute('data-wave-theme', night ? 'night' : 'day');
    root.querySelectorAll('[data-wave-theme-toggle]').forEach(button => {
      button.textContent = night ? '☾' : '☀';
      button.setAttribute('aria-pressed', String(night));
      button.title = night ? 'Hiện tại là chế độ tối, nhấn để chuyển sang chế độ sáng' : 'Hiện tại là chế độ sáng, nhấn để chuyển sang chế độ tối';
    });
  };
  const receive = event => { if (valid(event.detail)) { mode = event.detail; paint(); } };
  const toggle = event => {
    const button = event.target.closest?.('[data-wave-theme-toggle]');
    if (!button || !root.contains(button)) return;
    // Cancels the summary's default toggle as well as its click propagation.
    event.preventDefault(); event.stopPropagation();
    mode = isNight() ? 'day' : 'night';
    hub.__waveUiThemeV1 = mode;
    try { hub.localStorage.setItem(key, mode); } catch {}
    hub.dispatchEvent(new hub.CustomEvent(eventName, { detail: mode }));
    paint();
  };
  const storage = event => { if (event.key === key) receive({detail: event.newValue || 'auto'}); };
  root.addEventListener('click', toggle);
  hub.addEventListener(eventName, receive);
  hub.addEventListener('storage', storage);
  media?.addEventListener?.('change', paint);
  paint();
  const dispose = () => {
    root.removeEventListener('click', toggle);
    hub.removeEventListener(eventName, receive);
    hub.removeEventListener('storage', storage);
    media?.removeEventListener?.('change', paint);
    view.removeEventListener('pagehide', dispose);
  };
  view.addEventListener('pagehide', dispose, {once:true});
  return { paint, dispose };
}

createWaveTheme();

// Apply the console preference to this independently rendered message frame.
function watchWaveRegexFont(view = window) {
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const paint = () => {
    const scale = hub.document.documentElement.style.getPropertyValue('--wave-regex-scale');
    view.document.documentElement.style.setProperty('--wave-regex-scale', scale || '1');
  };
  hub.addEventListener('wave-regex-font-change', paint);
  view.addEventListener('pagehide', () => hub.removeEventListener('wave-regex-font-change', paint), { once: true });
  paint();
}
watchWaveRegexFont();

// Trusted message-iframe code. Model text is read as data, never inserted as HTML.
// API/source baseline: Tavern Helper 4.11.3, e71c990607f6c92127151b1f8dad6c79fa03966e.
function createWavePanelRuntime(config) {
  const tags = {plan:'wave_plan',mind:'wave_mind',options:'wave_options',summary:'wave_summary',review:'wave_review',comment:'wave_comment'};
  // Mô hình đôi khi viết ngắt dòng thành dấu gạch chéo ngược hiển thị kèm ký tự n，Đoạn này được chuyển lại thành ngắt dòng thực tế trước, sau đó mới đưa vào phân tích và render.。
  const waveSquash = (value) => {
    let text = String(value ?? '');
    const B = String.fromCharCode(92);
    if (text.indexOf(B + 'n') === -1 && text.indexOf(B + 'r') === -1) return text;
    text = text.split(B + B).join(B);
    return text.split(B + 'r' + B + 'n').join('\n').split(B + 'n').join('\n').split(B + 'r').join('\n');
  };
  function extract(raw, kind) {
    if (typeof raw !== 'string' || !tags[kind]) return [];
    if (kind === 'plan') {
      const match = /<wave_plan>\s*([\s\S]*?)(?:<(\/)wave_plan>|(?=<(content)>)(?![\s\S]*<\/wave_plan>)|$)/i.exec(raw);
      return match ? [{text:waveSquash(match[1]), state:match[2] || match[3] ? '/' : ''}] : [];
    }
    const tag = tags[kind];
    return Array.from(raw.matchAll(new RegExp('<'+tag+'>[ \\t]*(?:\\r?\\n)?([\\s\\S]*?)<\\/'+tag+'>','gi')), match => ({text:waveSquash(match[1]),state:'/'}));
  }
  function inline(target, value, doc) {
    // Deliberately small Markdown subset: no HTML, links, images or commands.
    const tokens = /\*\*([^*\n]+)\*\*|`([^`\n]+)`|\*([^*\n]+)\*/g;
    let offset=0;
    for (const match of value.matchAll(tokens)) {
      target.append(doc.createTextNode(value.slice(offset,match.index)));
      const node=doc.createElement(match[1]!==undefined?'strong':match[2]!==undefined?'code':'em');
      node.textContent=match[1] ?? match[2] ?? match[3]; target.append(node);
      offset=match.index+match[0].length;
    }
    target.append(doc.createTextNode(value.slice(offset)));
  }
  function renderText(target, text, doc=document) {
    target.replaceChildren();
    let list=null, listType='';
    for (const line of text.trim().split(/\r?\n/)) {
      if (!line.trim()) {list=null;listType='';continue;}
      const item=/^\s*(?:(\d+)[.)、]\s*|([-+*])\s+)(.*)$/.exec(line);
      if (item) {
        const type=item[1]?'ol':'ul';
        if (!list || listType!==type) {list=doc.createElement(type);listType=type;if(item[1])list.start=Number(item[1]);target.append(list);}
        const li=doc.createElement('li');inline(li,item[3],doc);list.append(li);continue;
      }
      list=null;listType='';
      const heading=/^(#{1,4})\s+(.+)$/.exec(line);
      const node=doc.createElement(heading?'h'+Math.min(heading[1].length+1,5):'p');
      inline(node,heading?heading[2]:line,doc);target.append(node);
    }
    if (!target.childNodes.length) target.textContent='Mục này không có văn bản。';
  }
  function markerKind(html) {
    return /<meta name="wave-panel" content="(plan|mind|options|summary|review|comment)">/.exec(html || '')?.[1] ?? null;
  }
  function getFrameKind(frame) {
    // The regular renderer retains its original pre/code beside the iframe;
    // the streaming renderer supplies srcdoc. Blob mode can use the former too.
    const srcdoc=frame.getAttribute('srcdoc');
    if (srcdoc) return markerKind(srcdoc);
    const original=Array.from(frame.parentElement?.children || []).find(el=>el.tagName==='PRE')?.querySelector('code');
    if (original) return markerKind(original.textContent);
    try {return frame.contentDocument?.querySelector('meta[name="wave-panel"]')?.getAttribute('content') ?? null;} catch {return null;}
  }
  function occurrence(blockCount) {
    if (blockCount===1) return 0;
    const frame=window.frameElement;
    const floor=frame?.closest('.mes');
    if (!frame || !floor) throw new Error('Tin nhắn này có nhiều mục cùng loại nhưng ứng dụng không cung cấp khung chứa nhận diện được; vui lòng cập nhật TavernHelper rồi tải lại tin nhắn này.。');
    const frames=Array.from(floor.querySelectorAll('iframe[id^="TH-message--"]')).filter(el=>getFrameKind(el)===config.kind);
    const index=frames.indexOf(frame);
    if (index<0 || frames.length!==blockCount) throw new Error('Số lượng bảng cùng loại chưa khớp với tin nhắn gốc. Nếu tải lại vẫn bị, hãy kiểm tra xem có biểu thức chính quy (regex) nào ẩn bớt tiếng lòng không, cũng như khả năng tương thích giao diện của ứng dụng.。');
    return index;
  }
  let timer=null,disposed=false,last='',failures=0,actions=null,optionItems=[];
  function updateActions(state){
    for(const input of document.querySelectorAll('[name="wave-action-mode"]'))input.checked=input.value===state.mode;
    for(const button of document.querySelectorAll('[data-wave-choice]'))button.disabled=state.pending||state.submitted||button.hasAttribute('data-wave-unavailable');
    const feedback=document.querySelector('[data-wave-action-feedback]');
    if(feedback){feedback.textContent=state.feedback;feedback.toggleAttribute('data-error',state.error);}
  }
  function renderOptions(target,text){
    optionItems=actions.parse(text);
    if(!optionItems.length){renderText(target,text);const note=document.querySelector('[data-wave-action-feedback]');note.textContent='Số thứ tự tùy chọn chưa hoàn chỉnh; bạn có thể đọc văn bản gốc trước, chỉ các tùy chọn đủ từ 1 đến 5 mới có thể nhấn.。';note.setAttribute('data-error','');return;}
    target.replaceChildren();
    const list=document.createElement('ol');list.setAttribute('data-wave-choices','');
    for(const [index,item] of optionItems.entries()){
      const li=document.createElement('li'),button=document.createElement('button');
      button.type='button';button.setAttribute('data-wave-choice',String(index));
      if(item.unavailable)button.setAttribute('data-wave-unavailable','');
      const number=document.createElement('span');number.setAttribute('data-wave-choice-number','');number.textContent=String(item.number);
      const copy=document.createElement('span'),category=document.createElement('span');category.setAttribute('data-wave-choice-category','');category.textContent=item.category;
      copy.append(category,document.createTextNode(item.action));button.append(number,copy);li.append(button);list.append(li);
    }
    target.append(list);updateActions(actions.getState());
  }
  function dispose() {disposed=true;if(timer!==null)clearTimeout(timer);timer=null;actions?.dispose();}
  async function refresh() {
    if (disposed) return;
    const panel=document.querySelector('[data-wave-ui]'), copy=document.querySelector('[data-wave-copy]'), phase=document.querySelector('[data-wave-phase]');
    let busy=false;
    try {
      if (typeof getCurrentMessageId!=='function' || typeof getChatMessages!=='function') throw new Error('Không thể đọc tin nhắn này: Vui lòng đảm bảo bạn đang dùng giao diện tầng của TavernHelper và đã bật bộ render. Ứng dụng tương thích cũng cần cung cấp giao diện đọc tin nhắn.。');
      const id=getCurrentMessageId();
      const rows=await getChatMessages(id);
      const row=rows.find(item=>item.message_id===id);
      if (!row || typeof row.message!=='string') throw new Error('Nội dung tin nhắn này chưa được lưu hoặc chưa sẵn sàng; vui lòng đợi phản hồi hoàn tất rồi tải lại tin nhắn.。');
      const blocks=extract(row.message,config.kind);
      if (!blocks.length) throw new Error('Tin nhắn này thiếu mục tương ứng hoàn chỉnh, hoặc có regex khác đã thay đổi thẻ nguồn; vui lòng kiểm tra nội dung gốc.。');
      const block=blocks[occurrence(blocks.length)];
      if (!block) throw new Error('Không tìm thấy nội dung tương ứng với bảng này; vui lòng tải lại tin nhắn.。');
      busy=config.kind==='plan' && block.state==='';
      panel.setAttribute('data-wave-state',block.state);
      if (phase) {phase.textContent=busy?'Đang lên ý tưởng':'Đã lập kế hoạch xong';phase.toggleAttribute('data-wave-busy',busy);phase.toggleAttribute('data-wave-done',!busy);}
      const key=block.text+'\u0000'+block.state;
      if (last!==key) {
        if(config.kind==='options'&&actions)renderOptions(copy,block.text);
        else if(config.kind==='mind'){
          const name=/^\s*\*\*([^*\n]{1,24})\*\*\s*(?:\r?\n|$)/.exec(block.text);
          document.querySelector('[data-wave-title]').textContent=name?name[1]+' · Tiếng lòng':'Tiếng lòng nhân vật';
          renderText(copy,name?block.text.slice(name[0].length):block.text);
        }else renderText(copy,block.text);
        last=key;
      }
      panel.removeAttribute('data-wave-error');failures=0;
    } catch (error) {
      panel.setAttribute('data-wave-error','');
      copy.textContent=error instanceof Error?error.message:String(error);
      panel.open=true;
      if (phase) phase.textContent='Đọc chưa hoàn tất';
      failures++;
    }
    // Only incomplete planning or a bounded initial retry needs a timer.
    if (!disposed && (busy || failures>0 && failures<4)) timer=setTimeout(refresh,700);
  }
  function start() {
    window.addEventListener('pagehide',dispose,{once:true});
    window.addEventListener('unload',dispose,{once:true});
    if(config.kind==='options'&&typeof createWaveActionController==='function'){
      actions=createWaveActionController(window);actions.subscribe(updateActions);
      document.querySelector('[data-wave-action-modes]')?.addEventListener('change',event=>{if(event.target.name==='wave-action-mode')actions.setMode(event.target.value);});
      document.querySelector('[data-wave-copy]').addEventListener('click',event=>{
        const button=event.target.closest('[data-wave-choice]');
        if(!button||button.disabled)return;
        const item=optionItems[Number(button.getAttribute('data-wave-choice'))];
        if(item&&!item.unavailable)void actions.pick(item.action);
      });
    }
    refresh();
  }
  return {extract,renderText,markerKind,getFrameKind,start,dispose};
}

createWavePanelRuntime({"kind":"mind"}).start();
