// View preference only; the control lives in the existing panel heading.
function createWaveTheme(view = window, root = document.documentElement) {
  const key = 'wave-ui-theme-v1', eventName = 'wave-ui-theme-change-v1';
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const media = view.matchMedia?.('(prefers-color-scheme: dark)');
  const valid = value => ['auto', 'day', 'night'].includes(value);
  let mode = 'auto';
  try { mode = hub.localStorage.getItem(key) || 'auto'; } catch {}
  if (valid(hub.__waveUiThemeV1)) mode = hub.__waveUiThemeV1;
  if (!valid(mode)) mode = 'auto';
  const isNight = () => mode === 'night' || mode === 'auto' && !!media?.matches;
  const paint = () => {
    const night = isNight();
    root.setAttribute('data-wave-theme', night ? 'night' : 'day');
    root.querySelectorAll('[data-wave-theme-toggle]').forEach(button => {
      button.textContent = night ? '☾' : '☀';
      button.setAttribute('aria-pressed', String(night));
      button.title = night ? 'Hiện tại là chế độ tối, nhấn để chuyển sang chế độ sáng' : 'Hiện tại là chế độ sáng, nhấn để chuyển sang chế độ tối';
    });
  };
  const receive = event => { if (valid(event.detail)) { mode = event.detail; paint(); } };
  const toggle = event => {
    const button = event.target.closest?.('[data-wave-theme-toggle]');
    if (!button || !root.contains(button)) return;
    // Cancels the summary's default toggle as well as its click propagation.
    event.preventDefault(); event.stopPropagation();
    mode = isNight() ? 'day' : 'night';
    hub.__waveUiThemeV1 = mode;
    try { hub.localStorage.setItem(key, mode); } catch {}
    hub.dispatchEvent(new hub.CustomEvent(eventName, { detail: mode }));
    paint();
  };
  const storage = event => { if (event.key === key) receive({detail: event.newValue || 'auto'}); };
  root.addEventListener('click', toggle);
  hub.addEventListener(eventName, receive);
  hub.addEventListener('storage', storage);
  media?.addEventListener?.('change', paint);
  paint();
  const dispose = () => {
    root.removeEventListener('click', toggle);
    hub.removeEventListener(eventName, receive);
    hub.removeEventListener('storage', storage);
    media?.removeEventListener?.('change', paint);
    view.removeEventListener('pagehide', dispose);
  };
  view.addEventListener('pagehide', dispose, {once:true});
  return { paint, dispose };
}

createWaveTheme();

// Apply the console preference to this independently rendered message frame.
function watchWaveRegexFont(view = window) {
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const paint = () => {
    const scale = hub.document.documentElement.style.getPropertyValue('--wave-regex-scale');
    view.document.documentElement.style.setProperty('--wave-regex-scale', scale || '1');
  };
  hub.addEventListener('wave-regex-font-change', paint);
  view.addEventListener('pagehide', () => hub.removeEventListener('wave-regex-font-change', paint), { once: true });
  paint();
}
watchWaveRegexFont();

// Trusted message-iframe code. Model text is read as data, never inserted as HTML.
// API/source baseline: Tavern Helper 4.11.3, e71c990607f6c92127151b1f8dad6c79fa03966e.
function createWavePanelRuntime(config) {
  const tags = {plan:'wave_plan',mind:'wave_mind',options:'wave_options',summary:'wave_summary',review:'wave_review',comment:'wave_comment'};
  // Mô hình đôi khi viết ngắt dòng thành dấu gạch chéo ngược hiển thị kèm ký tự n，Đoạn này được chuyển lại thành ngắt dòng thực tế trước, sau đó mới đưa vào phân tích và render.。
  const waveSquash = (value) => {
    let text = String(value ?? '');
    const B = String.fromCharCode(92);
    if (text.indexOf(B + 'n') === -1 && text.indexOf(B + 'r') === -1) return text;
    text = text.split(B + B).join(B);
    return text.split(B + 'r' + B + 'n').join('\n').split(B + 'n').join('\n').split(B + 'r').join('\n');
  };
  function extract(raw, kind) {
    if (typeof raw !== 'string' || !tags[kind]) return [];
    if (kind === 'plan') {
      const match = /<wave_plan>\s*([\s\S]*?)(?:<(\/)wave_plan>|(?=<(content)>)(?![\s\S]*<\/wave_plan>)|$)/i.exec(raw);
      return match ? [{text:waveSquash(match[1]), state:match[2] || match[3] ? '/' : ''}] : [];
    }
    const tag = tags[kind];
    return Array.from(raw.matchAll(new RegExp('<'+tag+'>[ \\t]*(?:\\r?\\n)?([\\s\\S]*?)<\\/'+tag+'>','gi')), match => ({text:waveSquash(match[1]),state:'/'}));
  }
  function inline(target, value, doc) {
    // Deliberately small Markdown subset: no HTML, links, images or commands.
    const tokens = /\*\*([^*\n]+)\*\*|`([^`\n]+)`|\*([^*\n]+)\*/g;
    let offset=0;
    for (const match of value.matchAll(tokens)) {
      target.append(doc.createTextNode(value.slice(offset,match.index)));
      const node=doc.createElement(match[1]!==undefined?'strong':match[2]!==undefined?'code':'em');
      node.textContent=match[1] ?? match[2] ?? match[3]; target.append(node);
      offset=match.index+match[0].length;
    }
    target.append(doc.createTextNode(value.slice(offset)));
  }
  function renderText(target, text, doc=document) {
    target.replaceChildren();
    let list=null, listType='';
    for (const line of text.trim().split(/\r?\n/)) {
      if (!line.trim()) {list=null;listType='';continue;}
      const item=/^\s*(?:(\d+)[.)、]\s*|([-+*])\s+)(.*)$/.exec(line);
      if (item) {
        const type=item[1]?'ol':'ul';
        if (!list || listType!==type) {list=doc.createElement(type);listType=type;if(item[1])list.start=Number(item[1]);target.append(list);}
        const li=doc.createElement('li');inline(li,item[3],doc);list.append(li);continue;
      }
      list=null;listType='';
