    if(!optionItems.length){renderText(target,text);const note=document.querySelector('[data-wave-action-feedback]');note.textContent='Số thứ tự tùy chọn chưa hoàn chỉnh; bạn có thể đọc văn bản gốc trước, chỉ các tùy chọn đủ từ 1 đến 5 mới có thể nhấn.。';note.setAttribute('data-error','');return;}
